-- RIPS FAQ 데이터 (2026-11-07, 전달받은 FAQ 15건)
-- 홈페이지 RIPS > 이용 전 체크사항(FAQ) 에 표시 (한국어 · 영어 · 베트남어), 관리자 > 고객문의 > FAQ 에서 수정 가능
-- 기존 테스트 데이터 및 이전 샘플 FAQ 삭제 후 등록 (같은 질문이 이미 있으면 등록하지 않음)
SET NAMES utf8mb4;

DELETE FROM faq WHERE question IN ('질문ko', '11', 'RIPS는 어떤 서비스인가요?', '어떤 업체가 RIPS를 이용할 수 있나요?', 'RIPS 이용 신청은 어떻게 하나요?', '판매 데이터는 어떻게 입력하나요?', '아직 판매가 없는 상품도 등록할 수 있나요?', '재고 소진 예상일과 추천 발주수량은 어떻게 정해지나요?', '재고소진, 즉시발주, 발주필요는 어떻게 다른가요?', '발주는 어떻게 하나요?', '발주 후 진행 상황은 어디서 확인하나요?', '발주를 수정하거나 취소할 수 있나요?', '통관 관련 안내는 어디서 확인하나요?', '테스트베드는 무엇이고 어떻게 신청하나요?', '상품 등록 시 바코드는 꼭 입력해야 하나요?', '업체 정보나 비밀번호는 어떻게 변경하나요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT 'RIPS 신청 후 도입까지 얼마나 걸리나요?', 'How long does it take to start using RIPS after applying?', 'Sau khi đăng ký, mất bao lâu để bắt đầu sử dụng RIPS?', '상담 및 상품·시장 정보 확인 후 필요한 등록 및 운영 범위를 협의합니다. 준비된 상품은 비교적 빠르게 진행할 수 있으며, 현지 상품등록이나 추가 인증이 필요한 경우 일정이 더 소요될 수 있습니다.', 'After a consultation and a review of your product and market information, we agree on the registration and operation scope you need. Products that are already prepared can move forward relatively quickly, while products that require local product registration or additional certification may take longer.', 'Sau khi tư vấn và xem xét thông tin sản phẩm, thị trường, chúng tôi sẽ thống nhất phạm vi đăng ký và vận hành cần thiết. Sản phẩm đã chuẩn bị sẵn có thể triển khai tương đối nhanh, còn sản phẩm cần đăng ký tại Việt Nam hoặc chứng nhận bổ sung có thể mất thêm thời gian.', 1, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = 'RIPS 신청 후 도입까지 얼마나 걸리나요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT '어떤 상품을 등록할 수 있나요?', 'What products can be registered?', 'Có thể đăng ký những sản phẩm nào?', '현재는 베트남 시장 진출 가능성이 있는 한국 식품을 중심으로 운영합니다. 상품 특성, 유통기한, 보관조건, 현지 등록 가능 여부 등을 검토한 후 등록 범위를 안내합니다.', 'We currently focus on Korean food products with potential in the Vietnamese market. After reviewing product characteristics, shelf life, storage conditions and whether local registration is possible, we will advise you on the registration scope.', 'Hiện tại chúng tôi tập trung vào thực phẩm Hàn Quốc có tiềm năng thâm nhập thị trường Việt Nam. Sau khi xem xét đặc tính sản phẩm, hạn sử dụng, điều kiện bảo quản và khả năng đăng ký tại Việt Nam, chúng tôi sẽ hướng dẫn phạm vi đăng ký.', 2, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = '어떤 상품을 등록할 수 있나요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT 'RIPS는 언제까지 무료로 제공되나요?', 'How long is RIPS free of charge?', 'RIPS được cung cấp miễn phí đến khi nào?', '기본 상담과 초기 검토는 무료로 진행할 수 있습니다. 이후 상품등록, 현지 운영, 물류, 데이터 분석 등 실제 서비스 이용 범위에 따라 비용이 발생할 수 있으며 사전에 안내드립니다.', 'The basic consultation and initial review are free. After that, fees may apply depending on the services you actually use, such as product registration, local operations, logistics and data analysis, and we will inform you in advance.', 'Tư vấn cơ bản và đánh giá ban đầu được thực hiện miễn phí. Sau đó, chi phí có thể phát sinh tùy theo phạm vi dịch vụ thực tế như đăng ký sản phẩm, vận hành tại Việt Nam, logistics, phân tích dữ liệu và sẽ được thông báo trước.', 3, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = 'RIPS는 언제까지 무료로 제공되나요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT '베트남에 이미 유통 중인 상품도 이용할 수 있나요?', 'Can products already distributed in Vietnam use RIPS?', 'Sản phẩm đang được phân phối tại Việt Nam có sử dụng được không?', '가능합니다. 기존 판매 데이터나 유통 현황을 기반으로 판매분석, 안전재고 예측, 발주예측, 판매기회 분석 등 필요한 기능부터 활용할 수 있습니다.', 'Yes. Based on your existing sales data and distribution status, you can start with the features you need, such as sales analysis, safety stock forecasting, order forecasting and sales opportunity analysis.', 'Có. Dựa trên dữ liệu bán hàng và tình hình phân phối hiện có, bạn có thể bắt đầu từ các chức năng cần thiết như phân tích bán hàng, dự báo tồn kho an toàn, dự báo đặt hàng và phân tích cơ hội bán hàng.', 4, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = '베트남에 이미 유통 중인 상품도 이용할 수 있나요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT '베트남에 처음 진출하는 상품도 이용할 수 있나요?', 'Can products entering Vietnam for the first time use RIPS?', 'Sản phẩm lần đầu vào Việt Nam có sử dụng được không?', '가능합니다. 상품 적합성 검토부터 현지 상품등록, 테스트 판매, 판매데이터 분석, 유통 확대까지 단계적으로 진행할 수 있습니다.', 'Yes. We can proceed step by step, from reviewing product suitability to local product registration, test sales, sales data analysis and distribution expansion.', 'Có. Có thể triển khai từng bước, từ đánh giá mức độ phù hợp của sản phẩm, đăng ký sản phẩm tại Việt Nam, bán thử, phân tích dữ liệu bán hàng đến mở rộng phân phối.', 5, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = '베트남에 처음 진출하는 상품도 이용할 수 있나요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT '현지 상품등록이나 통관도 지원하나요?', 'Do you support local product registration and customs clearance?', 'Có hỗ trợ đăng ký sản phẩm tại Việt Nam và thông quan không?', '상품별 필요 절차를 확인하고 원산지 증명, 현지 상품등록, 정식 통관 등 실제 유통에 필요한 업무를 연계합니다. 필요한 범위는 상품별로 달라질 수 있습니다.', 'We check the procedures required for each product and coordinate the work needed for actual distribution, such as certificates of origin, local product registration and formal customs clearance. The required scope may vary by product.', 'Chúng tôi kiểm tra thủ tục cần thiết cho từng sản phẩm và kết nối các công việc cần cho phân phối thực tế như chứng nhận xuất xứ, đăng ký sản phẩm tại Việt Nam và thông quan chính ngạch. Phạm vi cần thiết có thể khác nhau tùy sản phẩm.', 6, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = '현지 상품등록이나 통관도 지원하나요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT 'RIPS에서는 어떤 데이터를 볼 수 있나요?', 'What data can I see in RIPS?', 'Có thể xem những dữ liệu nào trên RIPS?', '상품별 판매량, 재고, 출고, 지역별 판매 흐름, 판매 추이 등 운영 데이터를 기반으로 필요한 정보를 제공합니다. 이를 통해 재고와 발주를 보다 효율적으로 관리할 수 있습니다.', 'RIPS provides the information you need based on operational data such as sales volume, stock and shipments by product, regional sales flow and sales trends. This helps you manage inventory and orders more efficiently.', 'RIPS cung cấp thông tin cần thiết dựa trên dữ liệu vận hành như sản lượng bán, tồn kho, xuất kho theo sản phẩm, diễn biến bán hàng theo khu vực và xu hướng bán hàng. Nhờ đó bạn có thể quản lý tồn kho và đặt hàng hiệu quả hơn.', 7, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = 'RIPS에서는 어떤 데이터를 볼 수 있나요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT '안전재고와 발주예측은 어떻게 하나요?', 'How are safety stock and order forecasts made?', 'Tồn kho an toàn và dự báo đặt hàng được thực hiện như thế nào?', '실제 판매량과 재고 흐름, 리드타임, 행사·프로모션 등 운영정보를 반영해 적정 재고와 발주 시점 및 수량을 제안합니다.', 'We suggest appropriate stock levels and the timing and quantity of orders by reflecting operational information such as actual sales volume, stock flow, lead time, and events and promotions.', 'Chúng tôi đề xuất mức tồn kho phù hợp cùng thời điểm và số lượng đặt hàng dựa trên thông tin vận hành như sản lượng bán thực tế, biến động tồn kho, thời gian giao hàng (lead time), sự kiện và khuyến mãi.', 8, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = '안전재고와 발주예측은 어떻게 하나요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT '판매가 부진하면 어떤 도움을 받을 수 있나요?', 'What help can I get if sales are slow?', 'Nếu doanh số kém thì có thể nhận được hỗ trợ gì?', '판매 흐름과 지역·채널별 데이터를 분석해 문제를 확인하고, 재고조정, 판매전략 변경, 신규 채널 검토, 상품 보완 등 다음 실행 방향을 제안합니다.', 'We analyze sales flow and data by region and channel to identify the problem, then suggest next steps such as stock adjustment, changes to sales strategy, review of new channels and product improvement.', 'Chúng tôi phân tích diễn biến bán hàng và dữ liệu theo khu vực, kênh để xác định vấn đề, sau đó đề xuất hướng thực hiện tiếp theo như điều chỉnh tồn kho, thay đổi chiến lược bán hàng, xem xét kênh mới và cải tiến sản phẩm.', 9, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = '판매가 부진하면 어떤 도움을 받을 수 있나요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT '판매가 잘 되면 유통 확대도 가능한가요?', 'If sales go well, can distribution be expanded?', 'Nếu bán tốt thì có thể mở rộng phân phối không?', '네. 판매데이터와 시장반응을 근거로 추가 유통처 제안, 발주 확대, 지역 확장 등 후속 수출 확대를 검토할 수 있습니다.', 'Yes. Based on sales data and market response, we can review further export expansion, such as proposing additional distributors, increasing orders and expanding to new regions.', 'Có. Dựa trên dữ liệu bán hàng và phản ứng thị trường, chúng tôi có thể xem xét mở rộng xuất khẩu tiếp theo như đề xuất thêm điểm phân phối, tăng đơn hàng và mở rộng khu vực.', 10, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = '판매가 잘 되면 유통 확대도 가능한가요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT '테스트 판매만 진행할 수도 있나요?', 'Can I run test sales only?', 'Có thể chỉ bán thử nghiệm không?', '가능합니다. 대규모 수출 전에 베트남 시장에서 실제 고객반응을 확인하고, 그 결과를 바탕으로 수출 지속 여부나 상품 개선 방향을 판단할 수 있습니다.', 'Yes. Before large-scale exports, you can check actual customer response in the Vietnamese market and use the results to decide whether to continue exporting or how to improve the product.', 'Có. Trước khi xuất khẩu quy mô lớn, bạn có thể kiểm tra phản ứng thực tế của khách hàng tại thị trường Việt Nam và dựa vào kết quả đó để quyết định có tiếp tục xuất khẩu hay cần cải tiến sản phẩm theo hướng nào.', 11, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = '테스트 판매만 진행할 수도 있나요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT 'RIPS를 이용하려면 어떤 자료가 필요한가요?', 'What materials are needed to use RIPS?', 'Cần chuẩn bị những tài liệu gì để sử dụng RIPS?', '기본적으로 회사 및 상품정보, 제품 이미지, 공급가, 유통기한, 보관조건, 성분 및 제조정보 등이 필요합니다. 상품에 따라 추가 자료를 요청할 수 있습니다.', 'Basically, we need company and product information, product images, supply prices, shelf life, storage conditions, and ingredient and manufacturing information. Additional materials may be requested depending on the product.', 'Về cơ bản cần thông tin công ty và sản phẩm, hình ảnh sản phẩm, giá cung cấp, hạn sử dụng, điều kiện bảo quản, thành phần và thông tin sản xuất. Tùy sản phẩm, chúng tôi có thể yêu cầu thêm tài liệu.', 12, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = 'RIPS를 이용하려면 어떤 자료가 필요한가요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT '판매데이터는 외부에 공개되나요?', 'Is sales data disclosed to third parties?', 'Dữ liệu bán hàng có bị công khai ra bên ngoài không?', '아닙니다. 기업 및 상품별 운영 데이터는 해당 기업의 서비스 제공과 분석을 위해 활용하며, 외부에 임의로 공개하지 않습니다.', 'No. Operational data for each company and product is used to provide services and analysis to that company and is not disclosed to third parties without permission.', 'Không. Dữ liệu vận hành theo doanh nghiệp và sản phẩm chỉ được sử dụng để cung cấp dịch vụ và phân tích cho chính doanh nghiệp đó, không tùy ý công khai ra bên ngoài.', 13, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = '판매데이터는 외부에 공개되나요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT '모든 상품이 입점이나 수출로 연결되나요?', 'Will every product lead to a store listing or export?', 'Có phải mọi sản phẩm đều được đưa vào cửa hàng hoặc xuất khẩu không?', '모든 상품이 자동으로 입점되는 것은 아닙니다. 시장성, 가격경쟁력, 상품등록 가능 여부, 현지 유통 적합성 등을 검토한 후 진행 여부를 결정합니다.', 'Not every product is listed automatically. We decide whether to proceed after reviewing marketability, price competitiveness, whether product registration is possible and suitability for local distribution.', 'Không phải mọi sản phẩm đều tự động được đưa vào cửa hàng. Chúng tôi quyết định có triển khai hay không sau khi xem xét tính thị trường, khả năng cạnh tranh về giá, khả năng đăng ký sản phẩm và mức độ phù hợp với phân phối tại Việt Nam.', 14, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = '모든 상품이 입점이나 수출로 연결되나요?');

INSERT INTO faq (question, question_en, question_vn, answer, answer_en, answer_vn, orderby, use_yn, created_at, created_by)
SELECT 'RIPS는 단순 데이터 서비스인가요?', 'Is RIPS just a data service?', 'RIPS chỉ là dịch vụ dữ liệu đơn thuần phải không?', '아닙니다. RIPS는 판매·재고·발주 데이터를 실제 유통 운영과 연결하는 실행형 플랫폼입니다. 데이터 분석에서 끝나지 않고 상품등록, 공급, 발주, 재고관리, 시장 확대까지 연결하는 것을 목표로 합니다.', 'No. RIPS is an execution-oriented platform that connects sales, stock and order data with actual distribution operations. It does not stop at data analysis; it aims to connect product registration, supply, ordering, inventory management and market expansion.', 'Không. RIPS là nền tảng thực thi kết nối dữ liệu bán hàng, tồn kho, đặt hàng với hoạt động phân phối thực tế. Không chỉ dừng lại ở phân tích dữ liệu, RIPS hướng đến kết nối cả đăng ký sản phẩm, cung ứng, đặt hàng, quản lý tồn kho và mở rộng thị trường.', 15, 1, NOW(), '관리자' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM faq WHERE question = 'RIPS는 단순 데이터 서비스인가요?');
